"""Genera el informe de la copia web desde los resultados medidos."""
from pathlib import Path
import json
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4

ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'output/pdf'
OUT.mkdir(parents=True,exist_ok=True)
H=json.loads((ROOT/'output/validation/holdout-108.json').read_text())
C=json.loads((ROOT/'output/validation/comparison-162.json').read_text())
TRAIN=json.loads((ROOT/'output/validation/training-refinement.json').read_text())
MODEL=json.loads((ROOT/'models/courier/strategy_model.json').read_text())
S=H['summaries']['SmartCourier']
blue=colors.HexColor('#1976d2');navy=colors.HexColor('#142a40');muted=colors.HexColor('#566b80')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleWeb',fontName='Helvetica-Bold',fontSize=25,leading=30,textColor=navy,spaceAfter=15))
styles.add(ParagraphStyle(name='HeadWeb',fontName='Helvetica-Bold',fontSize=12,leading=16,textColor=navy,spaceBefore=15,spaceAfter=7))
styles.add(ParagraphStyle(name='BodyWeb',fontName='Helvetica',fontSize=10,leading=15,textColor=navy,spaceAfter=8))
styles.add(ParagraphStyle(name='SmallWeb',fontName='Helvetica',fontSize=8,leading=11,textColor=muted,spaceAfter=5))
styles.add(ParagraphStyle(name='TableWeb',fontName='Helvetica',fontSize=9,leading=13,textColor=navy))
styles.add(ParagraphStyle(name='LabelWeb',fontName='Helvetica-Bold',fontSize=9,leading=13,textColor=blue,spaceAfter=9))
def p(text,style='BodyWeb'):return Paragraph(text,styles[style])
def money(n):return f'${n:,.2f}'
def table(rows,widths):
 t=Table([[p(escape(str(x)),'TableWeb') for x in row] for row in rows],colWidths=widths,hAlign='LEFT',repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#eaf3fb')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#dfe7ef'))]))
 return t
def footer(canvas,doc):
 canvas.setStrokeColor(colors.HexColor('#dfe7ef'));canvas.line(42,43,A4[0]-42,43)
 canvas.setFillColor(muted);canvas.setFont('Helvetica',8);canvas.drawString(42,29,'SmartCourier AI | Copia web | 12 septiembre 2026');canvas.drawRightString(A4[0]-42,29,f'{doc.page}')
def build(name,story):
 SimpleDocTemplate(str(OUT/name),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=40,bottomMargin=57,title=name.replace('_',' ').replace('.pdf',''),author='SmartCourier AI').build(story,onFirstPage=footer,onLaterPages=footer)

story=[p('VALIDACIÓN Y FUNCIONAMIENTO','LabelWeb'),p('SmartCourier AI<br/>La copia web, probada.','TitleWeb'),p('La aplicación está disponible localmente en <b>http://127.0.0.1:5173</b>. La copia usa su propia base smartcourier_web, API en 5002 y servicio Python en 8001. El código móvil se conserva en frontend-mobile/.'),p('Qué quedó funcionando','HeadWeb'),p('Cuenta y sesión; comparador con pausa, reanudación y velocidades; seis eventos; mapa Leaflet; recuperación de rutas al recargar en pausa; historial filtrado; ajustes; y laboratorio <b>Agente Courier</b> para consultar el modelo entrenado con variables editables.'),p('Pruebas terminadas','HeadWeb'),table([['Verificación','Resultado'],['Backend con PostgreSQL y Python reales','76 pruebas aprobadas'],['Navegador Chromium','2 recorridos completos aprobados; escritorio y móvil'],['Compilación de producción','Vite genera frontend/dist/'],['Regresión económica','Pago sin propina, costo marginal, plazos e inputs inválidos'],['Recuperación','Snapshot, replay y reinicio sin cobros duplicados']],[191,320]),p('Resultados en escenarios independientes','HeadWeb'),table([['Módulo','Ganancia positiva','En cero','Con pérdida'],['Comparador web','162 / 162','0','0'],['Courier entrenado',f"{S['positive_shifts']} / 108",S['zero_shifts'],S['negative_shifts']]],[190,130,90,101]),p('Son resultados de simulación. No prueban ganancias garantizadas en condiciones reales ni que SmartCourier gane a otra estrategia en todos los turnos. Los dos módulos tienen modelos de costo diferentes.','SmallWeb'),PageBreak(),p('01 / CÓMO DECIDE COURIER','LabelWeb'),p('Seguridad, costo<br/>y valor del tiempo.','TitleWeb'),p('El tier 1 decide ACCEPT o SKIP sin llamar al modelo dentro de la ventana de decisión. El tier 2 en Python calcula el salario de reserva con parámetros entrenados. La consulta web prepara una estrategia independiente por solicitud; no altera el turno global de los jueces.'),p('Secuencia aplicada en el código','HeadWeb'),p('<b>1.</b> Validar datos. Distancias, pagos, peso, volumen y tiempos numéricos deben ser finitos y no negativos; surge debe ser mayor que cero.<br/><b>2.</b> Planear el viaje: ir a recoger, esperar preparación y entregar. Si hay un pedido en curso, comparar terminarlo primero con recoger el nuevo primero.<br/><b>3.</b> Aplicar seguridad: zonas nocturnas, descanso, calor, fin del turno y capacidad. El pago no puede revocar estos rechazos.<br/><b>4.</b> Comprobar pedidos simultáneos y plazos; máximo dos pedidos, ruta factible.<br/><b>5.</b> Exigir que el pago base con surge supere el combustible, a centavos, sin depender de propina.<br/><b>6.</b> Comparar tarifa ajustada con salario de reserva. Un empate a centavos se acepta.'),p('Fórmulas económicas','HeadWeb'),p('<b>Bruto estimado</b> = pago base × surge + propina estimada<br/><b>Combustible</b> = kilómetros marginales × costo por km<br/><b>Neto estimado</b> = bruto estimado - combustible<br/><b>Neto sin propina</b> = pago base × surge - combustible; debe ser &gt; 0<br/><b>Tarifa ajustada/h</b> = 60 × (neto - costo del próximo traslado vacío) / (minutos marginales + espera estimada en destino). El tiempo marginal se limita como mínimo a un minuto.'),p('Límites conservados','HeadWeb'),p('Zonas 3 y 10: no entregar de 22:00 a 06:00. Descanso de 20 min tras 240 min continuos. Ventana de calor 12:00-16:00: máximo 90 min continuos. Fin del turno leído del estado. Margen de seguridad: <b>5 min</b>.'),table([['Vehículo','Combustible/km','Peso / volumen','Velocidad base'],['Bici','$0.00','7 kg / 25 L','14 km/h'],['Moto','$1.20','12 kg / 45 L','28 km/h'],['Auto','$2.40','40 kg / 200 L','22 km/h']],[80,135,155,141]),p('Fuentes del código: backend/src/courier/{fastPath,trip,safety,config,demandModel}.js y optimization-service/main.py. La bicicleta tiene combustible cero en este protocolo; no significa que trabajar en bici no tenga otros costos.','SmallWeb'),PageBreak(),p('02 / ENTRENAMIENTO Y RESULTADOS','LabelWeb'),p('Medir sin ajustar<br/>con las respuestas del examen.','TitleWeb'),p('courier/ aporta protocolo, esquemas, ejemplos y validadores; no es un historial masivo de entregas reales. Los flujos son sintéticos reproducibles. Demanda y reservas se entrenaron con semillas <b>1-54</b>. Se probaron reservas ×1, ×0.75, ×0.5, ×0 y ×1.25 por vehículo, y factores de fin de turno 0.5, 0.25 y 0. Los parámetros originales siguieron siendo los mejores de esos candidatos y se conservaron.'),p('Reserva aprendida, MXN/h antes del ajuste de fin','HeadWeb'),table([['Vehículo','Mañana','Comida','Tarde','Cena','Noche']]+[[v]+[MODEL['params']['vehicles'][v][b] for b in ['morning','lunch','afternoon','dinner','night']] for v in ['moto','car','bike']],[86,85,85,85,85,85]),p('Se reduce a la mitad durante los últimos 45 min. Factores de lluvia y surge de la estrategia: 1. El hash/versionado identifica el artefacto: '+MODEL['version']+'.','SmallWeb'),p('Courier: 108 semillas nuevas, 130001-130108','HeadWeb'),table([['Política con restricciones','Neto medio/turno'],['SmartCourier',money(S['mean_net_mxn'])],['AcceptAll + Safety',money(H['summaries']['AcceptAllSafety']['mean_net_mxn'])],['GreedyRate + Safety',money(H['summaries']['GreedyRateSafety']['mean_net_mxn'])]],[330,181]),p(f"804 pedidos aceptados, cero aceptaciones con neto sin propina no positivo, <b>cero violaciones de seguridad</b>, 2 entregas tardías y cero diferencias en el replay de 108 turnos. Neto medio eliminando todas las propinas de los pedidos seleccionados: <b>{money(S['mean_net_without_tips_mxn'])}</b>. P99 máximo del cálculo rápido: {S['max_p99_ms']} ms; presupuesto 50 ms, sin incluir HTTP ni refresco de estrategia."),p('Dónde aún puede perder frente a otra política','HeadWeb'),p('SmartCourier no gana todos los enfrentamientos: frente a AcceptAll + Safety registra '+str(H['paired']['AcceptAllSafety']['wins'])+' victorias, '+str(H['paired']['AcceptAllSafety']['ties'])+' empates y '+str(H['paired']['AcceptAllSafety']['losses'])+' derrotas por ingreso neto del turno. En auto, GreedyRate + Safety tiene mayor media; en bici, AcceptAll + Safety. Dos turnos de auto terminan con ingreso cero. No se reajustaron parámetros con estas semillas.'),p('Las referencias +Safety pasan por las mismas restricciones de ruta y piso de neto sin propina. El reporte oficial adicional de 30 semillas conserva OurAgent $466.17 frente a $458.36 y $448.39; AcceptAll sin reglas logra $543.71 con 87 violaciones.','SmallWeb'),PageBreak(),p('03 / COMPARADOR WEB Y OPERACIÓN','LabelWeb'),p('Una web operativa.<br/>Resultados trazables.','TitleWeb'),p('El comparador usa puntajes, planificación anticipada y agrupación de pedidos; conserva la física compartida entre Baseline y SmartCourier. Costos estimados por km: bici $0.40, moto $2.00 y auto $4.50, incluyendo combustible, mantenimiento y depreciación. Estos resultados no se mezclan con Courier.'),p('162 pruebas: 54 semillas nuevas × 3 escenarios','HeadWeb'),table([['Vehículo (54 pruebas)','Neto Smart','Neto Baseline','Victorias/h'],*[[v,money(r['smart_mean_net_mxn']),money(r['baseline_mean_net_mxn']),str(r['wins_by_net_hour'])+'/54'] for v,r in C['by_vehicle'].items()]],[170,115,125,101]),p(f"Media total de SmartCourier: <b>{money(C['summary']['smart_mean_net_mxn'])}</b> por turno frente a {money(C['summary']['baseline_mean_net_mxn'])}. Todas las 162 pruebas terminan con ganancia; mínimo {money(C['summary']['min_net_mxn'])}. Supera a Baseline por neto/hora trabajada en 152/162. Escenarios: normal, tráfico severo y cierre vial, con rutas estimadas deterministas."),p('No es una garantía universal','HeadWeb'),p('El comparador registró 189 entregas tardías frente a 190 de Baseline. En moto y bici tuvo más retrasos que Baseline, aunque mayores ingresos. Courier no incluye desgaste, impuestos ni gastos personales; los resultados sin propina son una sensibilidad contable de los pedidos seleccionados, no un reentrenamiento. Un cambio futuro de pago, costo, cancelación o ruta puede cambiar la rentabilidad real.'),p('Arranque local y archivos de referencia','HeadWeb'),p('Desde smartcourier-web/: <b>npm start</b> inicia web, API y Python en segundo plano; <b>npm run status</b> verifica los tres servicios; <b>npm stop</b> los detiene. Registra una cuenta nueva. El Mac debe permanecer encendido. README_WEB.md contiene instalación, pruebas y límites de despliegue.'),p('Pruebas: npm run test:backend; npm run test:web; npm run build.<br/>Evaluación: node backend/scripts/courier/refineWeb.js holdout; node backend/scripts/validateComparison.js. Los resultados por semilla y decisiones están en output/validation/. El estado inicial se conserva en COPY_MANIFEST.json y las nueve modificaciones quedan registradas en COPY_AMENDMENTS.json.','SmallWeb'),p('Este informe actualiza la documentación original de la copia. El sistema queda listo para demostración local; un despliegue público requiere hosting, HTTPS, base propia y aislamiento de los endpoints de jueces.','SmallWeb')]
build('SmartCourier_Web_Validacion.pdf',story)

improvements=[p('HOJA DE MEJORAS / UNA PÁGINA','LabelWeb'),p('Qué se corrigió<br/>y qué conviene mejorar.','TitleWeb'),p('Aplicado y probado en la copia web','HeadWeb'),p('<b>Economía:</b> piso positivo de pago base sin propina; costo marginal corregido al terminar primero una entrega anterior; validación de números inválidos.<br/><b>Factibilidad:</b> plazos de entrega individuales y de pedidos en curso; se conservan las cinco reglas y el margen de cinco minutos.<br/><b>Web:</b> mapa recuperable desde snapshot, filtros accesibles, laboratorio Courier autenticado e independiente, arranque en segundo plano.'),p('Propuestas que no se adoptaron','HeadWeb'),p('Bajar indiscriminadamente el salario de reserva, incluido cero en bicicleta, redujo el ingreso de entrenamiento. No se aplicó. Los factores de fin 0.25 y 0 no mejoraron al 0.5. Tampoco se bajó el margen de seguridad de 5 a 2 min para ganar más a costa de factibilidad.'),p('Siguientes mejoras, con criterio de aceptación','HeadWeb'),table([['Prioridad / cambio','Cómo verificarlo'],['1. Costos reales y datos observados','Añadir desgaste, comisiones y costos de trabajo a una variante del modelo; calibrar con entregas reales. Mantener una evaluación temporal separada.'],['2. Evitar turnos sin ingreso','Investigar dos turnos de auto en cero y la selección en bici. Entrenar en un conjunto nuevo; aprobar solo con mejor ingreso fuera de ajuste y cero violaciones.'],['3. Reducir retrasos y riesgo de ruta','Modelar incertidumbre de preparación y tráfico. Medir puntualidad e ingreso juntos; conservar restricciones obligatorias.'],['4. Preparar operación pública','Aislar estado por usuario, proteger endpoints de jueces, habilitar HTTPS, respaldo de base y seguimiento de errores. Verificar aislamiento entre cuentas.']],[175,336]),Spacer(1,10),p('<b>Referencia actual:</b> comparador: 162/162 turnos positivos; Courier: 106 positivos, 2 en cero y 0 con pérdida en 108 pruebas. Rentabilidad media mayor que las referencias seguras, con casos donde otra política gana más.','SmallWeb'),p('No volver a usar las semillas de reporte observadas para ajustar un candidato y presentarlas luego como evidencia independiente. Conservar las versiones anteriores y publicar también los casos desfavorables.','SmallWeb')]
build('SmartCourier_Hoja_de_Mejoras_Web.pdf',improvements)

summary={k:v for k,v in H.items() if k not in ['per_shift']}
text=f'''# Validación de SmartCourier Web - 12 septiembre 2026

76 pruebas backend aprobadas; 2 recorridos Chromium aprobados; build Vite correcto.

## Courier entrenado

Modelo congelado: `{MODEL['version']}`. Entrenamiento 1-54. Holdout 130001-130108.

106 turnos positivos, 2 en cero, 0 pérdidas; media ${S['mean_net_mxn']:.2f} netos de combustible. Sin propinas de los pedidos seleccionados: ${S['mean_net_without_tips_mxn']:.2f}. 804 aceptaciones, ninguna con neto sin propina no positivo. Cero violaciones de seguridad, 2 retrasos, 0 diferencias de replay. Máximo p99 {S['max_p99_ms']} ms (solo fast path).

Los candidatos de umbral probados en entrenamiento no mejoraron a los originales: se conservaron los parámetros. No se disminuyó el margen de cinco minutos. Las correcciones son de costos marginales, piso de beneficio sin propina, validación y plazos. El holdout conserva las mismas decisiones del modelo anterior con esas correcciones comunes; no se atribuye una mejora de ingresos inexistente al ajuste.

## Comparador web

54 semillas nuevas (150001-150054) por tres escenarios, 162 pruebas. Las 162 producen beneficio positivo; mínimo ${C['summary']['min_net_mxn']:.2f}. Media SmartCourier ${C['summary']['smart_mean_net_mxn']:.2f} frente a Baseline ${C['summary']['baseline_mean_net_mxn']:.2f}. SmartCourier gana por neto/hora en 152/162. Registra 189 entregas tardías frente a 190 de Baseline. Rutas estimadas deterministas; costos por km $0.40/$2.00/$4.50 para bici/moto/auto.

## Interpretación

No equivale a ganancia garantizada ni a superioridad en cada turno. Courier tiene dos turnos de auto sin ingresos; en promedio auto pierde frente a GreedyRate+Safety y bici frente a AcceptAll+Safety. El comparador también pierde algunos enfrentamientos y tiene retrasos. Courier mide neto de combustible; no todos los costos reales están incluidos. Las propinas del simulador se pagan como fueron estimadas; el escenario sin propinas mostrado solo resta las propinas de los pedidos ya elegidos.

La carpeta courier aporta protocolo y ejemplos, no un historial masivo real. La evidencia se obtiene con flujos sintéticos reproducibles, no con entregas observadas en campo.

## Archivos verificables

- `output/validation/training-refinement.json`: candidatos evaluados solo en entrenamiento.
- `output/validation/holdout-108.json`: métricas y enfrentamientos por semilla.
- `output/validation/holdout-decisions.jsonl`: decisiones del holdout.
- `output/validation/comparison-162.json`: resultados por semilla y escenario.
- `courier/results_table.csv`: reporte oficial separado, semillas 90001-90030.
- `COPY_AMENDMENTS.json`: modificaciones frente a la copia inicial.
- `README_WEB.md`: instalación, operación y pruebas.

## Resultados Courier completos

```json
{json.dumps(summary,ensure_ascii=False,indent=2)}
```
'''
(ROOT/'output/validation/VALIDACION_WEB.md').write_text(text)
print('PDFs y VALIDACION_WEB.md generados.')
